mapper.select:
select  from nad_revenue r left join sys_user u on u.user_id = r.recorded_by

     and (r.title like concat('%', #{q}, '%') or r.reference like concat('%', #{q}, '%')) 
     and r.source = #{source} 
     and r.received_on >= #{from} 
     and r.received_on <= #{to} 

order by r.received_on desc, r.id desc

select currency, sum(amount) as total, count(*) as count from nad_revenue

     and received_on >= #{from} 
     and received_on <= #{to} 

group by currency

select source as bucket, currency, sum(amount) as total, count(*) as count from nad_revenue

     and received_on >= #{from} 
     and received_on <= #{to} 

group by source, currency
order by total desc
